import numpy as np
def comps(I,color):
    A=np.array(I); H,W=A.shape; seen=np.zeros_like(A,dtype=bool); out=[]
    for i in range(H):
        for j in range(W):
            if A[i,j]==color and not seen[i,j]:
                st=[(i,j)]; seen[i,j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and A[ny,nx]==color and not seen[ny,nx]:
                            seen[ny,nx]=True; st.append((ny,nx))
                out.append(cells)
    return out
